INSERT INTO action_plans (id, organization_id, title, description, theme_code, responsible_unit, status, percentage_complete, budget_allocated, budget_executed) VALUES ('act-01', 'org-sjrr', 'Modernização e Retrofit do Sistema de Climatização (Chillers)', 'Substituição das condensadoras antigas por equipamentos com tecnologia Inverter de alta eficiência e automação predial horária.', NULL, 'Seção de Infraestrutura Predial (SEINFRA)', 'EM_ANDAMENTO', 65, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO action_plans (id, organization_id, title, description, theme_code, responsible_unit, status, percentage_complete, budget_allocated, budget_executed) VALUES ('act-02', 'org-sjrr', 'Campanha "Adote sua Caneca": Descarte Zero de Copos e Garrafas Plásticas', 'Distribuição de canecas e garrafas térmicas institucionais e eliminação definitiva de copos descartáveis e garrafas plásticas individuais.', NULL, 'Comissão Gestora do PLS / SEMAT', 'CONCLUIDA', 100, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO action_plans (id, organization_id, title, description, theme_code, responsible_unit, status, percentage_complete, budget_allocated, budget_executed) VALUES ('act-03', 'org-sjrr', 'Instalação de Arejadores e Válvulas Hidráulicas Economizadoras', 'Substituição de 92% das torneiras manuais por acionamento hidromecânico temporizado e bacias com duplo acionamento.', NULL, 'Seção de Infraestrutura Predial', 'CONCLUIDA', 100, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO action_plans (id, organization_id, title, description, theme_code, responsible_unit, status, percentage_complete, budget_allocated, budget_executed) VALUES ('act-04', 'org-sjrr', 'Migração Integral para Telefonia IP (VoIP Teams) e Rescisão Troncos E1', 'Conclusão da portabilidade dos ramais para nuvem e cancelamento do contrato legado STFC com a concessionária Oi.', NULL, 'Núcleo de Tecnologia da Informação (NUTEC)', 'ATRASADA', 45, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO action_plans (id, organization_id, title, description, theme_code, responsible_unit, status, percentage_complete, budget_allocated, budget_executed) VALUES ('act-05', 'org-sjrr', 'Desmaterialização de Processos Administrativos e Cotas de Impressão', 'Migração de 100% dos formulários de RH e almoxarifado para o SEI e fixação de cotas no software SafeQ.', NULL, 'Secretaria Administrativa / Almoxarifado', 'EM_ANDAMENTO', 75, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO action_plans (id, organization_id, title, description, theme_code, responsible_unit, status, percentage_complete, budget_allocated, budget_executed) VALUES ('act-06', 'org-sjrr', 'Fortalecimento da Coleta Seletiva Solidária e Triagem In Loco', 'Ampliação dos pontos de entrega voluntária (PEVs) e capacitação dos colaboradores da limpeza para separação gravimétrica de resíduos.', NULL, 'Comissão Gestora do PLS', 'EM_ANDAMENTO', 70, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO action_plans (id, organization_id, title, description, theme_code, responsible_unit, status, percentage_complete, budget_allocated, budget_executed) VALUES ('act-07', 'org-sjrr', 'Adequação dos Editais de Licitação à Nova Lei nº 14.133/2021 e Guia CNJ', 'Revisão dos modelos de Termos de Referência (TR) e Estudos Técnicos Preliminares (ETP), inserindo cláusulas compulsórias de sustentabilidade socioambiental no Plano de Contratações Anual (PCA).', NULL, 'Núcleo de Compras e Contratos (NUCAP)', 'EM_ANDAMENTO', 80, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO action_plans (id, organization_id, title, description, theme_code, responsible_unit, status, percentage_complete, budget_allocated, budget_executed) VALUES ('act-08', 'org-sjrr', 'Implantação do Programa Justiça Carbono Zero (Resolução CNJ nº 594/2024)', 'Elaboração do Inventário Anual de Emissões de GEE (Escopos 1, 2 e 3), plano de descarbonização da SJRR e contratação de compensação residual via créditos de preservação florestal na Amazônia.', NULL, 'Comissão Gestora do PLS / Gestão Socioambiental', 'EM_ANDAMENTO', 75, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO action_plans (id, organization_id, title, description, theme_code, responsible_unit, status, percentage_complete, budget_allocated, budget_executed) VALUES ('act-09', 'org-sjrr', 'Otimização de Roteiros da Frota Oficial e Mandados Jurisdicionais', 'Roteirização integrada dos mandados cumpridos pelos Oficiais de Justiça, uso prioritário de etanol/biocombustível nos veículos flex e expansão de audiências virtuais.', NULL, 'Central de Mandados / Seção de Transporte', 'EM_ANDAMENTO', 85, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO action_plans (id, organization_id, title, description, theme_code, responsible_unit, status, percentage_complete, budget_allocated, budget_executed) VALUES ('act-10', 'org-sjrr', 'Logística Reversa de Eletroeletrônicos e Lâmpadas com Emissão de CDF', 'Desfazimento de equipamentos de TI obsoletos e lâmpadas fluorescentes através de entidade gestora certificada, com Certificado de Destinação Final (CDF).', NULL, 'Seção de Material e Patrimônio (SEMAT) / NUTEC', 'EM_ANDAMENTO', 90, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO action_plans (id, organization_id, title, description, theme_code, responsible_unit, status, percentage_complete, budget_allocated, budget_executed) VALUES ('act-11', 'org-sjrr', 'Capacitação Contínua em Sustentabilidade e Compras Públicas Verdes', 'Realização de oficinas e cursos EAD sobre os ODS da Agenda 2030 da ONU, contratações sustentáveis na Lei 14.133/2021 e sensibilização socioambiental.', NULL, 'Seção de Desenvolvimento e Avaliação de Pessoas (SELEP)', 'EM_ANDAMENTO', 60, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO action_plans (id, organization_id, title, description, theme_code, responsible_unit, status, percentage_complete, budget_allocated, budget_executed) VALUES ('act-12', 'org-sjrr', 'Programa de Qualidade de Vida no Trabalho (QVT) e Saúde Mental', 'Ações de ergonomia presencial e no teletrabalho, programas de acolhimento psicossocial, campanhas de vacinação e ginástica laboral preventiva.', NULL, 'Núcleo de Saúde e Bem-Estar (NUSAU)', 'EM_ANDAMENTO', 80, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO action_plans (id, organization_id, title, description, theme_code, responsible_unit, status, percentage_complete, budget_allocated, budget_executed) VALUES ('act-13', 'org-sjrr', 'Ações Afirmativas de Equidade, Diversidade e Acessibilidade Predial', 'Monitoramento da representatividade feminina e de pessoas negras em cargos de liderança e adequação de acessibilidade predial conforme NBR 9050 na sede da SJRR.', NULL, 'Comitê de Equidade, Diversidade e Acessibilidade SJRR', 'EM_ANDAMENTO', 70, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO action_plans (id, organization_id, title, description, theme_code, responsible_unit, status, percentage_complete, budget_allocated, budget_executed) VALUES ('act-14', 'org-sjrr', 'Automação Documental com IA e Redução de Despesas de Custeio (RDC)', 'Adoção de inteligência artificial para leitura e conciliação de faturas de concessionárias (E-Extrator SISPLS) e automação de fluxos no SEI, mensurando a economia de despesas correntes.', NULL, 'Núcleo de Tecnologia da Informação (NUTEC)', 'EM_ANDAMENTO', 75, NULL, NULL) ON CONFLICT (id) DO NOTHING;
